#pragma once
#include "../../support.hpp"
#include "hash.hpp"
namespace algs {
template<class K,class V>class OpenAddressingHashMap{struct Slot{int state=0;std::optional<std::pair<K,V>>entry;};std::vector<Slot>slots;int count=0,tombstones=0;std::function<std::uint32_t(const K&)>hasher;int find(const K&k)const{int i=hasher(k)%slots.size();for(int p=0;p<int(slots.size());++p){auto&s=slots[i];if(s.state==0)return -1;if(s.state==1&&s.entry->first==k)return i;i=(i+1)%slots.size();}return -1;}void resize(int n){auto all=entries();slots.assign(n,{});count=tombstones=0;for(auto&e:all)set(e.first,e.second);}public:explicit OpenAddressingHashMap(std::function<std::uint32_t(const K&)>h=defaultHasher<K>,int n=16):slots(std::max(2,n)),hasher(h){}int size()const{return count;}OpenAddressingHashMap&set(K k,V v){if((count+tombstones+1)*2>int(slots.size()))resize(int(slots.size())*2);int i=hasher(k)%slots.size(),deleted=-1;while(slots[i].state){auto&s=slots[i];if(s.state==2){if(deleted<0)deleted=i;}else if(s.entry->first==k){s.entry->second=v;return *this;}i=(i+1)%slots.size();}if(deleted>=0){i=deleted;--tombstones;}slots[i].state=1;slots[i].entry=std::pair<K,V>{k,v};++count;return *this;}std::optional<V>get(const K&k)const{int i=find(k);return i<0?std::optional<V>{}:slots[i].entry->second;}bool has(const K&k)const{return find(k)>=0;}bool erase(const K&k){int i=find(k);if(i<0)return false;slots[i].state=2;slots[i].entry.reset();--count;++tombstones;return true;}std::vector<std::pair<K,V>>entries()const{std::vector<std::pair<K,V>>r;for(auto&s:slots)if(s.state==1)r.push_back(*s.entry);return r;}};
}
